/**
 * robots.txt (PLAN.md §6.4), pointing at the sitemap generated by
 * @astrojs/sitemap.
 */
import type { APIRoute } from 'astro';

export const GET: APIRoute = ({ site }) => {
  const siteUrl = site ?? new URL('https://silaparasetti-lohith-portfolio.vercel.app');
  const sitemapUrl = new URL('sitemap-index.xml', siteUrl).href;

  const body = [
    'User-agent: *',
    'Allow: /',
    `Sitemap: ${sitemapUrl}`,
    '',
  ].join('\n');

  return new Response(body, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
};
